const MB=1024*1024,GB=1024*MB,MAX_NONSTREAM_FILE=250*MB,MAX_STREAM_WAV=16*GB,MAX_FILES=10000,RESULT_FOLDER="MP3_轉換結果",RENDER_LIMIT=300;
